import json, os

H = os.path.dirname(os.path.abspath(__file__))


def E(name, kind, lon, lat, year, winner, text):
    return {"name": name, "kind": kind, "lon": lon, "lat": lat, "year": year, "winner": winner, "text": text}


def M(side, commander, label, path):
    return {"side": side, "commander": commander, "label": label, "path": path}


def F(label, path):
    return {"path": path, "label": label}


def T(*lists):
    return [{"side": i, "polities": list(l)} for i, l in enumerate(lists) if l]


def S(year, label, title, text, territories, fronts, moves, events):
    return {"year": year, "label": label, "title": title, "text": text, "territories": territories,
            "fronts": fronts, "moves": moves, "events": events}


def minus(a, b):
    return [x for x in a if x not in b]


